//! Code the project did not write is out of scope by default: vendored directories and
//! generated files are not counted by the probe, not swept, not in the census and not in
//! workload discovery; the probe names what it left out; `dla run init --include` brings a
//! path back. Through the binary, on small trees laid out the way real projects are.

use std::{fs, path::Path};

use assert_cmd::Command;
use serde_json::Value;

fn write(root: &Path, rel: &str, text: &str) {
    let p = root.join(rel);
    fs::create_dir_all(p.parent().unwrap()).unwrap();
    fs::write(p, text).unwrap();
}

fn dla(project: &Path, args: &[&str]) -> (i32, Value) {
    let mut c = Command::cargo_bin("dla").unwrap();
    c.arg("--project").arg(project);
    for var in [
        "DLA_RUN",
        "DLA_DEFAULT_BUDGET",
        "DLA_CONSENT_TIERS",
        "DLA_CONSENT_RAW_VALUES",
        "CLAUDE_SESSION_ID",
        "CLAUDE_CODE_SESSION_ID",
        "DLA_DATA_DIR",
    ] {
        c.env_remove(var);
    }
    let o = c.args(args).output().unwrap();
    let text = String::from_utf8(o.stdout).unwrap();
    (
        o.status.code().unwrap(),
        serde_json::from_str(&text).unwrap_or(Value::Null),
    )
}

fn ok(project: &Path, args: &[&str]) -> Value {
    let (code, v) = dla(project, args);
    assert_eq!((code, &v["ok"]), (0, &Value::Bool(true)), "{args:?}: {v}");
    v
}

/// A Python project that ships a vendored C and Node project (`vendor/llhttp`, with a
/// Makefile and a package.json), a vendored Python package, and a C file generated by Cython.
fn project(dir: &Path) {
    write(dir, "app/__init__.py", "");
    write(
        dir,
        "app/main.py",
        "import functools\n\nCACHE = {}\n\n\n@functools.lru_cache(None)\ndef price(k):\n    return k\n\n\ndef put(k, v):\n    CACHE[k] = v\n",
    );
    write(
        dir,
        "app/_speedups.c",
        "/* Generated by Cython 3.0.10 */\nstatic void *gtable[64];\nvoid g_add(int i, void *x) { gtable[i] = x; }\n",
    );
    write(dir, "vendor/llhttp/package.json", "{\"name\":\"llhttp\"}\n");
    write(dir, "vendor/llhttp/Makefile", "all:\n\tcc -c src/p.c\n");
    write(
        dir,
        "vendor/llhttp/src/p.c",
        "static void *table[64];\nvoid p_add(int i, void *x) { table[i] = x; }\n",
    );
    write(
        dir,
        "vendor/llhttp/src/a.js",
        "const seen = new Map();\nmodule.exports = (k) => seen.set(k, 1);\n",
    );
    write(
        dir,
        "vendor/pylib/reg.py",
        "import functools\n\nREG = {}\n\n\n@functools.lru_cache(None)\ndef look(k):\n    return k\n\n\ndef add(k):\n    REG[k] = 1\n",
    );
}

fn runtimes(probe: &Value) -> Vec<String> {
    probe["summary"]["runtimes"]
        .as_array()
        .unwrap()
        .iter()
        .map(|r| r.as_str().unwrap().to_owned())
        .collect()
}

fn lines(probe: &Value) -> Vec<String> {
    probe["summary"]["left_out"]
        .as_array()
        .map(|a| a.iter().map(|l| l.as_str().unwrap().to_owned()).collect())
        .unwrap_or_default()
}

/// The `file:line` sites of every finding in the run's ledger.
fn sites(project: &Path) -> Vec<String> {
    let run = fs::read_to_string(project.join(".dla/current")).unwrap();
    let ledger = fs::read_to_string(project.join(".dla").join(run.trim()).join("ledger.jsonl"))
        .unwrap();
    ledger
        .lines()
        .filter_map(|l| serde_json::from_str::<Value>(l).ok())
        .filter(|v| v["type"] == "finding_added")
        .filter_map(|v| v["finding"]["site"].as_str().map(str::to_owned))
        .collect()
}

#[test]
fn vendored_and_generated_code_is_left_out_by_default() {
    let d = tempfile::tempdir().unwrap();
    let p = d.path();
    project(p);
    ok(p, &["run", "init", "--session-id", "t"]);

    let probe = ok(p, &["probe"]);
    assert_eq!(runtimes(&probe), ["python"], "{probe}");
    let l = lines(&probe);
    assert!(
        l.iter().any(|x| x == "vendor: vendored directory, 5 files"),
        "one line per directory with its file count: {l:?}"
    );
    assert!(
        l.iter()
            .any(|x| x.starts_with("generated files: 1 file (Generated by Cython")),
        "generated files as one line with a count: {l:?}"
    );
    // A runtime whose whole code base is left out is named, with the way back.
    assert!(
        l.iter().any(|x| x.starts_with("node: none of its 2 files")),
        "{l:?}"
    );
    assert!(
        l.iter().any(|x| x.starts_with("native: none of its")),
        "{l:?}"
    );
    assert!(
        probe["summary"]["left_out_note"]
            .as_str()
            .unwrap()
            .contains("--include"),
        "{probe}"
    );

    // The census has no entry there, for the runtime the probe reports and for the others.
    let py = ok(p, &["census", "--lang", "python"]);
    assert_eq!(py["summary"]["files"], 2, "app/__init__.py and app/main.py: {py}");
    for lang in ["native", "node"] {
        let c = ok(p, &["census", "--lang", lang]);
        assert_eq!(c["candidates"], 0, "{lang}: {c}");
        assert_eq!(c["summary"]["files"], 0, "{lang}: {c}");
    }
    // The sweep (the rules of DLA, and whatever analyzers are installed) never lists them.
    ok(p, &["sweep", "--lang", "python"]);
    let s = sites(p);
    assert!(!s.is_empty(), "the project's own code is analysed: {s:?}");
    for site in &s {
        assert!(
            site.starts_with("app/main.py:"),
            "only the project's own code is a candidate: {s:?}"
        );
    }
    // The decorated function is listed by its own site, once.
    assert!(s.iter().any(|x| x.starts_with("app/main.py:")), "{s:?}");
}

#[test]
fn include_brings_a_left_out_path_back() {
    let d = tempfile::tempdir().unwrap();
    let p = d.path();
    project(p);
    ok(
        p,
        &["run", "init", "--session-id", "t", "--include", "vendor/llhttp"],
    );
    let probe = ok(p, &["probe"]);
    let rts = runtimes(&probe);
    for want in ["python", "node", "native"] {
        assert!(rts.iter().any(|r| r == want), "{want} is back: {rts:?}");
    }
    let l = lines(&probe);
    assert!(
        l.iter().any(|x| x == "vendor: vendored directory, 1 file"),
        "what stays out is still named (vendor/pylib): {l:?}"
    );
    let native = ok(p, &["census", "--lang", "native"]);
    assert_eq!(native["summary"]["files"], 1, "{native}");
    assert!(
        sites(p)
            .iter()
            .any(|x| x.starts_with("vendor/llhttp/src/p.c:")),
        "the included file is listed: {:?}",
        sites(p)
    );
    // The generated file next to it stays out, and so does the vendored Python package.
    let all = sites(p);
    assert!(
        all.iter()
            .all(|x| !x.starts_with("app/_speedups.c") && !x.starts_with("vendor/pylib")),
        "{all:?}"
    );
    let node = ok(p, &["census", "--lang", "node"]);
    assert_eq!(node["summary"]["files"], 1, "{node}");

    // The run record says what was brought back.
    let st: Value = serde_json::from_str(
        &fs::read_to_string(
            p.join(".dla")
                .join(fs::read_to_string(p.join(".dla/current")).unwrap().trim())
                .join("state.json"),
        )
        .unwrap(),
    )
    .unwrap();
    assert_eq!(st["include"][0], "vendor/llhttp");
}

#[test]
fn include_must_name_an_existing_path_of_the_project() {
    let d = tempfile::tempdir().unwrap();
    project(d.path());
    for bad in ["../elsewhere", "/etc", "no/such/dir", ".", ""] {
        let (code, v) = dla(d.path(), &["run", "init", "--include", bad]);
        assert_eq!(code, 2, "{bad:?}: {v}");
        assert!(v["error"]["fix"].as_str().unwrap().contains("--include"));
    }
    assert!(
        !d.path().join(".dla").exists(),
        "a refused init writes nothing"
    );
}

#[test]
fn a_project_whose_root_is_named_vendor_is_analysed() {
    let d = tempfile::tempdir().unwrap();
    let root = d.path().join("vendor");
    project(&root);
    fs::remove_dir_all(root.join("vendor")).unwrap();
    ok(&root, &["run", "init", "--session-id", "t"]);
    let probe = ok(&root, &["probe"]);
    assert_eq!(runtimes(&probe), ["python"], "{probe}");
    let py = ok(&root, &["census", "--lang", "python"]);
    assert_eq!(py["summary"]["files"], 2, "{py}");
}

#[test]
fn a_project_made_of_a_vendor_tree_says_so_and_still_works() {
    let d = tempfile::tempdir().unwrap();
    let p = d.path();
    write(p, "vendor/lib/core.py", "CACHE = {}\n\n\ndef put(k):\n    CACHE[k] = 1\n");
    write(p, "README.md", "a project whose code lives in vendor/\n");
    ok(p, &["run", "init", "--session-id", "t"]);
    let probe = ok(p, &["probe"]);
    assert!(runtimes(&probe).is_empty(), "{probe}");
    let l = lines(&probe);
    assert!(
        l.iter()
            .any(|x| x.starts_with("python: none of its 1 file is analysed") && x.contains("vendor")),
        "{l:?}"
    );
    let c = ok(p, &["census", "--lang", "python"]);
    assert_eq!(c["candidates"], 0, "{c}");
    // And the way back works.
    fs::remove_dir_all(p.join(".dla")).unwrap();
    ok(p, &["run", "init", "--session-id", "t", "--include", "vendor"]);
    let probe = ok(p, &["probe"]);
    assert_eq!(runtimes(&probe), ["python"], "{probe}");
    assert_eq!(ok(p, &["census", "--lang", "python"])["candidates"], 1);
}

#[test]
fn packages_that_happen_to_be_called_external_are_kept() {
    let d = tempfile::tempdir().unwrap();
    let p = d.path();
    write(p, "app/external/__init__.py", "");
    write(p, "app/external/api.py", "CLIENTS = {}\n\n\ndef add(k):\n    CLIENTS[k] = 1\n");
    write(
        p,
        "src/main/java/org/acme/external/Client.java",
        "package org.acme.external;\n\npublic class Client {\n    static final java.util.Map<String, String> CACHE = new java.util.HashMap<>();\n}\n",
    );
    ok(p, &["run", "init", "--session-id", "t"]);
    let probe = ok(p, &["probe"]);
    assert!(lines(&probe).is_empty(), "{probe}");
    let rts = runtimes(&probe);
    assert!(rts.iter().any(|r| r == "python") && rts.iter().any(|r| r == "jvm"), "{rts:?}");
    assert_eq!(ok(p, &["census", "--lang", "python"])["summary"]["files"], 2);
}
